import React, { useEffect, useState } from "react";
import axios from "axios";
import {
  Card, CardHeader, CardBody, CardTitle,
  Row, Col, Table, Button, Form, FormGroup, Input,
  Modal, ModalHeader, ModalBody, ModalFooter
} from "reactstrap";

const API = "http://localhost:5000/api";
const getHeaders = () => ({ Authorization: `Bearer ${localStorage.getItem("token")}` });
const EMPTY = { title_en: "", title_ar: "", title_fr: "", description_en: "", description_ar: "", location_en: "", type: "Full Time", is_active: true, deadline: "" };

function AdminJobs() {
  const [items, setItems] = useState([]);
  const [form, setForm] = useState(EMPTY);
  const [editId, setEditId] = useState(null);
  const [modal, setModal] = useState(false);
  const [delId, setDelId] = useState(null);
  const [msg, setMsg] = useState("");

  const toast = (t) => { setMsg(t); setTimeout(() => setMsg(""), 4000); };
  const f = (k) => (e) => setForm({ ...form, [k]: e.target.value });

  const load = async () => {
    try { const r = await axios.get(`${API}/admin/jobs`, { headers: getHeaders() }); setItems(r.data); }
    catch (e) { console.error(e); }
  };

  useEffect(() => { load(); }, []);

  const save = async (e) => {
    e.preventDefault();
    try {
      if (editId) await axios.put(`${API}/admin/jobs/${editId}`, form, { headers: getHeaders() });
      else await axios.post(`${API}/admin/jobs`, form, { headers: getHeaders() });
      setModal(false); setForm(EMPTY); setEditId(null); load(); toast(editId ? "Updated!" : "Added!");
    } catch (e) { toast("Error: " + (e.response?.data?.error || e.message)); }
  };

  const del = async () => {
    try { await axios.delete(`${API}/admin/jobs/${delId}`, { headers: getHeaders() }); setDelId(null); load(); toast("Deleted!"); }
    catch (e) { toast("Error deleting"); }
  };

  const edit = (item) => { setForm({ ...item, deadline: item.deadline || "" }); setEditId(item.id); setModal(true); };
  const add  = () => { setForm(EMPTY); setEditId(null); setModal(true); };

  const expired = (d) => d && new Date(d) < new Date();

  return (
    <div className="content">
      {msg && <div className="alert alert-info">{msg}</div>}
      <Row>
        <Col md="12">
          <Card>
            <CardHeader className="d-flex justify-content-between align-items-center">
              <CardTitle tag="h4">Job Postings</CardTitle>
              <Button color="primary" onClick={add}>+ Add Job</Button>
            </CardHeader>
            <CardBody>
              <Table responsive>
                <thead className="text-primary">
                  <tr><th>#</th><th>Title (EN)</th><th>Type</th><th>Location</th><th>Deadline</th><th>Status</th><th>Actions</th></tr>
                </thead>
                <tbody>
                  {items.map((a, i) => (
                    <tr key={a.id}>
                      <td>{i+1}</td>
                      <td>{a.title_en}</td>
                      <td>{a.type}</td>
                      <td>{a.location_en || "—"}</td>
                      <td style={{ color: expired(a.deadline) ? "red" : "inherit" }}>{a.deadline || "—"}</td>
                      <td><span className={`badge badge-${a.is_active ? "success" : "secondary"}`}>{a.is_active ? "Active" : "Inactive"}</span></td>
                      <td>
                        <Button size="sm" color="warning" className="mr-1" onClick={() => edit(a)}>Edit</Button>
                        <Button size="sm" color="danger" onClick={() => setDelId(a.id)}>Delete</Button>
                      </td>
                    </tr>
                  ))}
                  {!items.length && <tr><td colSpan="7" className="text-center">No job postings yet</td></tr>}
                </tbody>
              </Table>
            </CardBody>
          </Card>
        </Col>
      </Row>

      <Modal isOpen={modal} toggle={() => setModal(false)} size="lg">
        <ModalHeader toggle={() => setModal(false)}>{editId ? "Edit Job" : "Add Job"}</ModalHeader>
        <Form onSubmit={save}>
          <ModalBody>
            <Row>
              <Col md="6"><FormGroup><label>Title (EN) *</label><Input required value={form.title_en} onChange={f("title_en")} /></FormGroup></Col>
              <Col md="6"><FormGroup><label>Title (AR)</label><Input value={form.title_ar} onChange={f("title_ar")} /></FormGroup></Col>
              <Col md="6"><FormGroup><label>Location (EN)</label><Input value={form.location_en} onChange={f("location_en")} placeholder="Amman, Jordan" /></FormGroup></Col>
              <Col md="6"><FormGroup><label>Type</label>
                <Input type="select" value={form.type} onChange={f("type")}>
                  <option>Full Time</option><option>Part Time</option><option>Contract</option><option>Internship</option>
                </Input>
              </FormGroup></Col>
              <Col md="6"><FormGroup><label>Deadline</label><Input type="date" value={form.deadline} onChange={f("deadline")} /></FormGroup></Col>
              <Col md="6"><FormGroup><label>Status</label>
                <Input type="select" value={form.is_active} onChange={e => setForm({...form, is_active: e.target.value === "true"})}>
                  <option value="true">Active</option><option value="false">Inactive</option>
                </Input>
              </FormGroup></Col>
              <Col md="12"><FormGroup><label>Description (EN)</label><Input type="textarea" rows="5" value={form.description_en} onChange={f("description_en")} /></FormGroup></Col>
              <Col md="12"><FormGroup><label>Description (AR)</label><Input type="textarea" rows="3" value={form.description_ar} onChange={f("description_ar")} /></FormGroup></Col>
            </Row>
          </ModalBody>
          <ModalFooter>
            <Button color="primary" type="submit">{editId ? "Update" : "Add"}</Button>
            <Button color="secondary" onClick={() => setModal(false)}>Cancel</Button>
          </ModalFooter>
        </Form>
      </Modal>

      <Modal isOpen={!!delId} toggle={() => setDelId(null)}>
        <ModalHeader>Confirm Delete</ModalHeader>
        <ModalBody>Are you sure you want to delete this job?</ModalBody>
        <ModalFooter><Button color="danger" onClick={del}>Delete</Button><Button color="secondary" onClick={() => setDelId(null)}>Cancel</Button></ModalFooter>
      </Modal>
    </div>
  );
}

export default AdminJobs;
